
import { IPackageInfo, appPackagesStoreV2 } from "@app/static";
import { autoWebViewJs } from "../";
import { isRealInAndroid } from "../is-in-android";
import { Log } from "@fanfanlo";

const fileLog = new Log(false, 'readAllPackages');
// fileLog.pause = true;
// fileLog.childrenPaused = true;

// import { readAllPackagesMockData } from "./mock-data/readAllPackages";
const script = `com.fanfanlo.droid.js.JsReceiver.readAllPackages();`

function readAllPackages():IPackageInfo[]{
    const fnLog = fileLog.sub(false, 'readAllPackages_fn');
    // fnLog.pause = true;
    // fnLog.childrenPaused = true;

    let res = autoWebViewJs.callScript<IPackageInfo[]>(script);

    let list: IPackageInfo[] = []
    if (res.javaResultData) {
        list = res.javaResultData as IPackageInfo[]
    }

    appPackagesStoreV2.savePackages(list)
    fnLog.log('complete, count=' + list.length)
    return list
}
async function mockReadAllPackages():Promise<IPackageInfo[]>{
    const fnLog = fileLog.sub(false, 'mockReadAllPackages_fn');
    // fnLog.pause = true;
    // fnLog.childrenPaused = true;

    if (appPackagesStoreV2.data.list.length > 0) {
        fnLog.log('use cached, count=' + appPackagesStoreV2.data.list.length)
        return appPackagesStoreV2.data.list
    }

    const mockData = await import('./mock-data/readAllPackages')
    const list = mockData.readAllPackagesMockData as IPackageInfo[]
    appPackagesStoreV2.savePackages(list)
    fnLog.log('complete, count=' + list.length)
    return list
}

export const readAllPackagesScript = {
    script,
    readAllPackages: isRealInAndroid ? readAllPackages : mockReadAllPackages,
}
